import re
seq=""
with open("region.fasta") as f:
    for l in f.read().splitlines():
        if not l.startswith(">"): seq+=l.strip().upper()
N=len(seq)
cons="GGCTTTGGTTACTAAGGG"  # 19 bp
L=len(cons)

def hamming(a,b): return sum(x!=y for x,y in zip(a,b))

hits=[]
for i in range(N-L+1):
    d=hamming(seq[i:i+L],cons)
    if d<=3:
        hits.append((i+1,d,seq[i:i+L]))
# merge overlapping within 5bp
merged=[]
for h in hits:
    if merged and h[0]-merged[-1][-1][0]<=5:
        merged[-1].append(h)
    else:
        merged.append([h])
print(f"Fuzzy hits (<=3 mismatches to {cons}) grouped:")
for g in merged:
    best=min(g,key=lambda x:x[1])
    print(f"  ~{g[0][0]}-{g[-1][0]+L-1}  best {best[0]} mism={best[1]} {best[2]}")
